export default function makeController() {
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  const dt = 0.01;

  let initialized = false;
  let vf = { x: 0, y: 0, z: 0 };
  let aFilt = { x: 0, y: 0, z: 0 };
  let distFast = { x: 0, y: 0, z: 0 };
  let distSlow = { x: 0, y: 0, z: 0 };
  let thrustLag = 0;
  let lastThrust = 0.45;

  let intX = 0, intY = 0, intZ = 0, intYaw = 0;
  let ref = { x: 0, y: 0, z: 0 };

  let activeGateIdx = 0;
  let activeGate = null;
  let phase = 'align';
  let settle = 0;
  let padY = 0.85;

  return {
    step(obs) {
      const p = obs.pos, v = obs.vel, att = obs.att, rates = obs.rates;

